import [printf] from "std/c.bpl";

# Define a struct with the 'struct' keyword
struct Person {
    name: string,
    age: int,
    height: float,
}

frame main() ret int {
    # Create a struct instance using struct literal syntax
    local alice: Person = Person {
        name: "Alice",
        age: 30,
        height: 1.65
    };

    # Access fields using the dot operator
    printf("Name: %s\n", alice.name);
    printf("Age: %d\n", alice.age);
    printf("Height: %.2f m\n", alice.height);

    # Create another person
    local bob: Person = Person {
        name: "Bob",
        age: 25,
        height: 1.80
    };

    printf("\n%s is %d years old\n", bob.name, bob.age);

    return 0;
}

import [printf] from "std/c.bpl";

struct Counter {
    value: int,
    name: string,
}

frame main() ret int {
    local counter: Counter = Counter {
        value: 0,
        name: "Click Counter"
    };

    printf("%s: %d\n", counter.name, counter.value);

    # Modify fields
    counter.value = counter.value + 1;
    printf("After increment: %d\n", counter.value);

    counter.value = counter.value + 10;
    printf("After adding 10: %d\n", counter.value);

    # Change the name
    counter.name = "Updated Counter";
    printf("%s: %d\n", counter.name, counter.value);

    return 0;
}

import [printf] from "std/c.bpl";

struct Point {
    x: int,
    y: int,
}

struct Rectangle {
    topLeft: Point,
    width: int,
    height: int,
}

frame main() ret int {
    # Create nested struct
    local rect: Rectangle = Rectangle {
        topLeft: Point { x: 10, y: 20 },
        width: 100,
        height: 50
    };

    printf("Rectangle:\n");
    printf("  Position: (%d, %d)\n", rect.topLeft.x, rect.topLeft.y);
    printf("  Size: %d x %d\n", rect.width, rect.height);

    # Calculate area
    local area: int = rect.width * rect.height;
    printf("  Area: %d\n", area);

    # Modify nested field
    rect.topLeft.x = 50;
    printf("  Moved to: (%d, %d)\n", rect.topLeft.x, rect.topLeft.y);

    return 0;
}

import [printf] from "std/c.bpl";

struct Point {
    x: int,
    y: int,
}

# Function that takes struct by value (copy)
frame printPoint(p: Point) {
    printf("Point(%d, %d)\n", p.x, p.y);
}

# Function that takes pointer to struct
frame movePoint(p: *Point, dx: int, dy: int) {
    p.x = p.x + dx;
    p.y = p.y + dy;
}

# Function that returns a struct
frame createPoint(x: int, y: int) ret Point {
    return Point { x: x, y: y };
}

# Calculate distance between two points
frame distance(p1: Point, p2: Point) ret int {
    local dx: int = p2.x - p1.x;
    local dy: int = p2.y - p1.y;
    if (dx < 0) { dx = -dx; }
    if (dy < 0) { dy = -dy; }
    return dx + dy;  # Manhattan distance
}

frame main() ret int {
    local p1: Point = createPoint(0, 0);
    local p2: Point = createPoint(3, 4);

    printf("p1: ");
    printPoint(p1);

    printf("p2: ");
    printPoint(p2);

    printf("Distance: %d\n", distance(p1, p2));

    # Move p1 using pointer
    movePoint(&p1, 5, 10);
    printf("p1 after move: ");
    printPoint(p1);

    return 0;
}

import [printf] from "std/c.bpl";

struct Student {
    name: string,
    grade: int,
}

frame printStudent(s: Student) {
    printf("  %s: %d\n", s.name, s.grade);
}

frame main() ret int {
    # Array of structs
    local students: Student[3] = [
        Student { name: "Alice", grade: 92 },
        Student { name: "Bob", grade: 85 },
        Student { name: "Charlie", grade: 78 }
    ];
    local count: int = 3;

    # Print all students
    printf("Class Roster:\n");
    loop (local i: int = 0; i < count; i = i + 1) {
        printStudent(students[i]);
    }

    # Find best student
    local best: int = 0;  # Index of best student
    loop (local j: int = 1; j < count; j = j + 1) {
        if (students[j].grade > students[best].grade) {
            best = j;
        }
    }
    printf("\nTop student: %s with %d\n", students[best].name, students[best].grade);

    # Calculate average
    local total: int = 0;
    loop (local k: int = 0; k < count; k = k + 1) {
        total = total + students[k].grade;
    }
    printf("Class average: %d\n", total / count);

    return 0;
}

