import [printf] from "std/c.bpl";

struct Book {
    title: string,
    author: string,
    year: int,
    pages: int,
}

frame main() ret int {
    local library: Book[3] = [
        Book { title: "1984", author: "Orwell", year: 1949, pages: 328 },
        Book { title: "Dune", author: "Herbert", year: 1965, pages: 412 },
        Book { title: "Foundation", author: "Asimov", year: 1951, pages: 244 }
    ];
    local count: int = 3;

    printf("Library:\n");
    loop (local i: int = 0; i < count; i = i + 1) {
        printf("  %s by %s (%d) - %d pages\n", 
            library[i].title, library[i].author, 
            library[i].year, library[i].pages);
    }

    local oldest: int = 0;
    loop (local j: int = 1; j < count; j = j + 1) {
        if (library[j].year < library[oldest].year) {
            oldest = j;
        }
    }

    printf("\nOldest: %s (%d)\n", library[oldest].title, library[oldest].year);

    return 0;
}
